/**
 * Writes everything on the site that is a colour: the stylesheet's custom properties, and the four
 * logo files.
 *
 * ## Why generated
 *
 * The brand purple used to appear in six places — the stylesheet, a `theme-color` meta tag, and four
 * `.svg` files — with nothing keeping them equal, and one of them had already drifted to a different
 * case. Now they all come from `@ramonda/theme`, so changing the purple is one line in one file.
 *
 * The generated files are committed, because they are served: `public/` is what the site ships, and
 * a favicon that only exists after a build step is a favicon missing from `npm run dev`.
 *
 *   node scripts/build-theme.mjs          # write them
 *   node scripts/build-theme.mjs --check  # fail if they are out of date (for CI)
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import {
  bloom,
  brand,
  declarations,
  logoGround,
  site,
  siteFaces,
  siteFonts,
} from "../../../packages/theme/src/index.ts";

const here = dirname(fileURLToPath(import.meta.url));
const publicDir = join(here, "..", "public");
const check = process.argv.includes("--check");

const HEADER = "/* GENERATED by scripts/build-theme.mjs from @ramonda/theme — do not edit. */";
const SVG_HEADER = "<!-- GENERATED by scripts/build-theme.mjs from @ramonda/theme — do not edit. -->";

const files = {
  "assets/tokens.css": [
    HEADER,
    "/* The site follows the reader's system preference; the devtools panel does not. See the",
    "   package for why those are two palettes rather than one. */",
    ...siteFaces.map((face) =>
      [
        "@font-face {",
        `  font-family: "${face.family}";`,
        `  font-style: ${face.style};`,
        `  font-weight: ${face.weight};`,
        "  font-display: swap;",
        `  src: url("/assets/fonts/${face.file}") format("${face.format}");`,
        "}",
      ].join("\n"),
    ),
    ":root {",
    `  --rmd-font-sans: ${siteFonts.sans};`,
    `  --rmd-font-mono: ${siteFonts.mono};`,
    declarations(site.light),
    "}",
    "@media (prefers-color-scheme: dark) {",
    "  :root {",
    declarations(site.dark, "    "),
    "  }",
    "}",
    "",
  ].join("\n"),

  "favicon.svg": [
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="-32 -32 64 64" role="img" aria-label="Ramonda">`,
    `  ${SVG_HEADER}`,
    `  <title>Ramonda</title>`,
    `  ${bloom()}`,
    `</svg>`,
    "",
  ].join("\n"),

  "apple-icon.svg": [
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="-90 -90 180 180" role="img" aria-label="Ramonda">`,
    `  ${SVG_HEADER}`,
    `  <title>Ramonda</title>`,
    `  <rect x="-90" y="-90" width="180" height="180" fill="${logoGround.paper}"/>`,
    `  <g transform="scale(2.55)">${bloom()}</g>`,
    `</svg>`,
    "",
  ].join("\n"),

  /** The one that is not the flower: a rounded tile with an R, for a context that needs a solid mark. */
  "icon-mono.svg": [
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="-32 -32 64 64" role="img" aria-label="Ramonda">`,
    `  ${SVG_HEADER}`,
    `  <title>Ramonda</title>`,
    `  <rect x="-30" y="-30" width="60" height="60" rx="15" fill="${brand.purple}"/>`,
    `  <text x="-1" y="1.5" text-anchor="middle" dominant-baseline="central"`,
    `        font-family="Palatino, Georgia, serif" font-size="42" font-weight="700"`,
    `        fill="#FFFFFF">R</text>`,
    `  <circle cx="15.5" cy="-15.5" r="5.4" fill="${brand.gold}"/>`,
    `</svg>`,
    "",
  ].join("\n"),

  /** The social card. Its fonts are named rather than loaded: it is rendered once, not by a browser. */
  "og.svg": [
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 630" role="img" aria-label="Ramonda — A TypeScript UI framework">`,
    `  ${SVG_HEADER}`,
    `  <title>Ramonda</title>`,
    `  <rect width="1200" height="630" fill="${logoGround.paper}"/>`,
    `  <rect width="1200" height="8" fill="${brand.purple}"/>`,
    `  <g transform="translate(330,315) scale(8.4)">${bloom()}</g>`,
    `  <text x="600" y="270" font-family="'DejaVu Sans', Verdana, sans-serif"`,
    `        font-size="118" font-weight="700" fill="${logoGround.heading}" letter-spacing="-3">ramonda</text>`,
    `  <text x="604" y="340" font-family="'DejaVu Sans', Verdana, sans-serif"`,
    `        font-size="40" fill="${logoGround.subheading}">A TypeScript UI framework</text>`,
    `  <text x="604" y="410" font-family="'DejaVu Serif', Georgia, serif"`,
    `        font-size="30" font-style="italic" fill="${brand.purple}">Every JSX tag is exactly one element.</text>`,
    `</svg>`,
    "",
  ].join("\n"),
};

const stale = [];
for (const [name, content] of Object.entries(files)) {
  const path = join(publicDir, name);
  let existing = null;
  try {
    existing = readFileSync(path, "utf8");
  } catch {
    // A file that is not there yet is written, not reported as a difference.
  }
  if (existing === content) continue;
  if (check) {
    stale.push(name);
    continue;
  }
  writeFileSync(path, content);
  console.log(`[theme] ${name}`);
}

if (stale.length > 0) {
  console.error(
    `[theme] out of date: ${stale.join(", ")}\n` + "        run `node scripts/build-theme.mjs` and commit the result.",
  );
  process.exit(1);
}
if (check) console.log("[theme] up to date");
